// Two thresholds rather than one, so a sensor hovering on the boundary
// does not announce itself over and over.
const READY_AT = 92;
const COLD_BELOW = 80;

const temp = Number(msg.payload);
if (Number.isNaN(temp)) {
    return null;
}

if (temp >= READY_AT) {
    msg.payload = 'ready';
} else if (temp <= COLD_BELOW) {
    msg.payload = 'cold';
} else {
    // In between: leave whatever was last announced standing.
    return null;
}
return msg;

// A notice is immediate. A scene would wait for the clock's own cycle,
// which can be fifteen seconds -- too long for something you are
// standing there waiting for.
if (msg.payload === 'ready') {
    msg.action = 'glance_clock.send_notice';
    msg.payload = {
        text: 'ESPRESSO [icon:130]',
        animation: 'pulse',
        color: 'lime_green',
        sound: 'bells',
    };
} else {
    msg.action = 'glance_clock.send_notice';
    msg.payload = {
        text: 'KALL',
        animation: 'none',
        color: 'royal_blue',
    };
}
return msg;
